// TestStructVersions recomputes each version stamp from the Go structure it
// versions and compares it with the value the C compiler produced from the
// pinned headers.
//
// MAKE_DCGM_VERSION(T, v) is sizeof(T) | v<<24, so a stamp that disagrees says
// the Go structure is not the size of the C structure. DCGM rejects such a
// stamp with ErrVerMismatch, which is why this has to fail here and not on a
// machine with a GPU.
func TestStructVersions(t *testing.T) {
	for _, c := range versionedStructs {
		got := uint32(c.size) | c.version<<24
		if got != c.stamp {
			t.Errorf("%s: Go size %d gives stamp 0x%x, header stamp 0x%x encodes C size %d",
				c.macro, c.size, got, c.stamp, c.stamp&0xffffff)
		}
	}
}

// TestStructVersionCoverage fails if the table shrank. A structure that stops
// being generated takes its stamp with it, and without a count that is a
// silent loss of surface rather than a test failure.
func TestStructVersionCoverage(t *testing.T) {
	const want = 96
	if got := len(versionedStructs); got != want {
		t.Errorf("versioned structures = %d, want %d", got, want)
	}
}
